import type { CarouselOptions } from "@starwind-ui/runtime/carousel";
import type { HTMLAttributes } from "astro/types";

type Props = HTMLAttributes<"div"> & {
  orientation?: "horizontal" | "vertical";
  opts?: CarouselOptions["opts"];
  autoInit?: boolean;
};

const { orientation = "horizontal", opts = {}, autoInit = true, ...rest } = Astro.props;
---

<div
  data-sw-carousel
  role="region"
  aria-roledescription="carousel"
  data-axis={orientation === "vertical" ? "y" : "x"}
  data-opts={JSON.stringify(opts)}
  data-auto-init={autoInit ? undefined : "false"}
  {...rest}
>
  <slot />
</div>

<script>
  import { createCarousel } from "@starwind-ui/runtime/carousel";
  import {
    registerAstroControllerLifecycle,
    trackAstroController,
  } from "../internal/controller-lifecycle";

  const getInitCandidates = (event: Event | undefined, selector: string): HTMLElement[] => {
    const initRoot =
      event?.type === "starwind:init" && event instanceof CustomEvent
        ? event.detail?.root
        : undefined;
    const scopedRoot: Document | DocumentFragment | Element = isQueryableRoot(initRoot)
      ? initRoot
      : document;
    const candidates = Array.from(scopedRoot.querySelectorAll<HTMLElement>(selector));

    if (scopedRoot instanceof Element && scopedRoot.matches(selector)) {
      candidates.unshift(scopedRoot as HTMLElement);
    }

    return candidates;
  };

  const isQueryableRoot = (value: unknown): value is Document | DocumentFragment | Element =>
    value instanceof Document || value instanceof DocumentFragment || value instanceof Element;

  const setupCarousels = (event?: Event) => {
    getInitCandidates(event, "[data-sw-carousel]").forEach((root) => {
      if (root.getAttribute("data-auto-init") === "false") return;

      trackAstroController("CarouselRoot", root, createCarousel(root));
    });
  };

  registerAstroControllerLifecycle("CarouselRoot", setupCarousels);
</script>

