import type { HTMLAttributes } from "astro/types";
import {
  createColorPickerInitialState,
  projectColorPickerInitialPart,
} from "@starwind-ui/runtime/color-picker";
import type {
  ColorPickerDirection,
  ColorPickerFormat,
  ColorPickerOptions,
  ColorPickerValue,
} from "@starwind-ui/runtime/color-picker";
import {
  createColorPickerRenderProjection,
  mergeColorPickerInitialStyles,
  type ColorPickerRenderProjection,
} from "./ColorPickerRenderProjection";

interface Props extends Omit<HTMLAttributes<"div">, "defaultValue" | "dir"> {
  value?: ColorPickerValue;
  defaultValue?: ColorPickerValue;
  format?: ColorPickerFormat;
  alpha?: boolean;
  allowEmpty?: boolean;
  disabled?: boolean;
  readOnly?: boolean;
  required?: boolean;
  name?: string;
  form?: string;
  locale?: string;
  dir?: ColorPickerDirection;
  getAriaValueText?: ColorPickerOptions["getAriaValueText"];
  getAreaRoleDescription?: ColorPickerOptions["getAreaRoleDescription"];
  getColorDescription?: ColorPickerOptions["getColorDescription"];
  children?: (initial: ColorPickerRenderProjection) => unknown;
}

const {
  value,
  defaultValue = "#000000",
  format = "hex",
  alpha = true,
  allowEmpty = false,
  disabled = false,
  readOnly = false,
  required = false,
  name,
  form,
  locale,
  dir,
  getAriaValueText,
  getAreaRoleDescription,
  getColorDescription,
  style,
  ...rest
} = Astro.props;
const initialState = createColorPickerInitialState({
  ...(value === undefined ? {} : { value }),
  defaultValue,
  format,
  alpha,
  allowEmpty,
  disabled,
  readOnly,
  required,
  name,
  form,
  locale,
  dir,
  getAriaValueText,
  getAreaRoleDescription,
  getColorDescription,
});
const rootInitial = projectColorPickerInitialPart(initialState, { part: "root" });
const initial = createColorPickerRenderProjection(initialState);
const content = Astro.slots.has("default") ? await Astro.slots.render("default", [initial]) : "";
const mergedStyle = mergeColorPickerInitialStyles(style, rootInitial);
---

<div {...rest} {...rootInitial.attributes} style={mergedStyle} data-sw-color-picker>
  <Fragment set:html={content} />
</div>

<script>
  import { createColorPicker } from "@starwind-ui/runtime/color-picker";
  import {
    registerAstroControllerLifecycle,
    trackAstroController,
  } from "../internal/controller-lifecycle";

  const getInitCandidates = (event: Event | undefined, selector: string): HTMLElement[] => {
    const initRoot =
      event?.type === "starwind:init" && event instanceof CustomEvent
        ? event.detail?.root
        : undefined;
    const scopedRoot: Document | DocumentFragment | Element = isQueryableRoot(initRoot)
      ? initRoot
      : document;
    const candidates = Array.from(scopedRoot.querySelectorAll<HTMLElement>(selector));

    if (scopedRoot instanceof Element && scopedRoot.matches(selector)) {
      candidates.unshift(scopedRoot as HTMLElement);
    }

    return candidates;
  };

  const isQueryableRoot = (value: unknown): value is Document | DocumentFragment | Element =>
    value instanceof Document || value instanceof DocumentFragment || value instanceof Element;

  const setupColorPickers = (event?: Event) => {
    getInitCandidates(event, "[data-sw-color-picker]").forEach((root) =>
      trackAstroController("ColorPickerRoot", root, createColorPicker(root)),
    );
  };

  registerAstroControllerLifecycle("ColorPickerRoot", setupColorPickers);
</script>

